    <View style={s.hadithCard}><Text style={s.quote}>“</Text><LiveBadge source="ISLAMIC.APP" /><Text numberOfLines={6} style={s.hadithText}>{data.hadith?.text || 'Loading today’s authenticated hadith…'}</Text><View style={s.hadithFoot}><Text style={s.meta}>{data.hadith ? `${data.hadith.collection.toUpperCase()} · ${data.hadith.number}` : ''}</Text>{ico('bookmark-outline',20,C.green)}</View></View>
