function ReaderScreen({route,navigation}:any){const chapter:Chapter=route.params.chapter;const[verses,setVerses]=useState<Verse[]>([]);const[error,setError]=useState('');const load=()=>getVerses(chapter.id).then(setVerses).catch(e=>setError(e.message));useEffect(()=>{load()},[chapter.id]);return <Page><View style={s.readerBar}><IconButton name="arrow-back" onPress={()=>navigation.goBack()}/><View style={{alignItems:'center'}}><Text style={s.readerName}>{chapter.name_simple}</Text><Text style={s.meta}>{chapter.verses_count} verses</Text></View><IconButton name="options-outline"/></View><ScrollView contentContainerStyle={s.readerScroll} showsVerticalScrollIndicator={false}><LinearGradient colors={['#302B68','#5C4FB2','#0B7891']} style={s.surahHead}><LiveBadge source="AL QURAN CLOUD"/><Text style={s.surahHeadAr}>{chapter.name_arabic}</Text><Text style={s.surahHeadEn}>{chapter.translated_name?.name}</Text><Text style={s.bismillah}>بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ</Text></LinearGradient>{error?<ErrorState message={error} retry={load}/>:!verses.length?<Spinner/>:verses.map(v=><View key={v.id} style={s.ayah}><View style={s.ayahTop}><Text style={s.ayahNo}>{v.verse_key}</Text><View style={s.row}><Pressable onPress={()=>v.audio&&Linking.openURL(v.audio)}>{ico('play-circle',25,C.green)}</Pressable><View style={{width:15}}/>{ico('bookmark-outline',20,C.green)}</View></View><Text style={s.ayahAr}>{v.text_uthmani}</Text><Text style={s.ayahTranslation}>{v.translation}</Text><Text style={s.ayahMeta}>Juz {v.juz} · Page {v.page} · Sahih International</Text></View>)}</ScrollView></Page>}
function QuranStack(){return <Stack.Navigator screenOptions={{headerShown:false}}><Stack.Screen name="QuranHome" component={QuranHome}/><Stack.Screen name="Reader" component={ReaderScreen}/></Stack.Navigator>}

