function ExploreHome({navigation}:any){const {width}=useWindowDimensions();const wide=width>=850;let index=0;return <Page><ScrollView contentContainerStyle={s.scroll} showsVerticalScrollIndicator={false}><TopBar overline="PRIVATE · SOURCED · FREE" title="Library" right={<IconButton name="search-outline"/>}/><Text style={s.intro}>Remembrance, trusted learning and practical tools—organized by purpose rather than hidden in a feature grid.</Text>{libraryGroups.map(group=><View key={group.label}><Text style={s.libraryKicker}>{group.label}</Text><Text style={s.libraryHeading}>{group.title}</Text><View style={s.exploreGrid}>{group.items.map(([iconName,title,desc]:any)=>{const delay=index++*40;return <MotionPress key={title} onPress={()=>navigation.navigate(title)} style={[s.exploreCard,wide&&s.exploreCardWide]}><View style={s.exploreCardInner}><MotionGlyph name={iconName} size={24} delay={delay}/><Text style={s.exploreTitle}>{title}</Text><Text style={s.exploreBody}>{desc}</Text><View style={s.exploreArrow}>{ico('arrow-forward',15,C.green)}</View></View></MotionPress>})}</View></View>)}<View style={s.apiPanel}><LiveBadge source="VERIFIED SOURCES"/><Text style={s.apiTitle}>Every text should show where it came from.</Text><Text style={s.apiText}>islamic.app · Al Quran Cloud · AlAdhan</Text></View></ScrollView></Page>}
function ToolBar({title,navigation}:any){return <View style={s.readerBar}><IconButton name="arrow-back" onPress={()=>navigation.goBack()}/><Text style={s.readerName}>{title}</Text><View style={{width:44}}/></View>}
function QiblaScreen({navigation}:any){const{location}=useAppLocation();const[direction,setDirection]=useState<number|null>(null);const[error,setError]=useState('');const load=async()=>{if(!location)return;setDirection(null);setError('');try{setDirection(await getQibla(location.latitude,location.longitude))}catch(e:any){setError(e.message)}};useEffect(()=>{load()},[location?.latitude,location?.longitude]);return <Page><ToolBar title="Qibla direction" navigation={navigation}/>{!location?<View style={s.dataPage}><LocationPrompt compact/></View>:<View style={s.toolPage}><LiveBadge source="ISLAMIC.APP"/><Text style={s.toolEyebrow}>{location.label}</Text>{error?<ErrorState message={error} retry={load}/>:direction===null?<Spinner/>:<><View style={s.compass}><Text style={s.north}>N</Text><View style={[s.compassArrow,{transform:[{rotate:`${direction}deg`}]}]}>{ico('navigate',74,C.green)}</View><View style={s.kaaba}><View style={s.kaabaGold}/></View></View><Text style={s.direction}>{direction.toFixed(1)}°</Text><Text style={s.directionText}>clockwise from true north</Text><Pressable onPress={load} style={s.primary}><Text style={s.primaryText}>Refresh direction</Text></Pressable></>}</View>}</Page>}
function TasbihScreen({navigation}:any){const[count,setCount]=useState(0);const tap=()=>{setCount(x=>x+1);if(Platform.OS!=='web')Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light)};return <Page><ToolBar title="Tasbih" navigation={navigation}/><View style={s.toolPage}><Text style={s.toolEyebrow}>CURRENT DHIKR</Text><Text style={s.tasbihAr}>سُبْحَانَ ٱللَّٰهِ</Text><Text style={s.directionText}>Glory be to Allah</Text><Pressable onPress={tap} style={({pressed})=>[s.counter,pressed&&s.counterPress]}><Text style={s.counterNo}>{count}</Text><Text style={s.counterGoal}>GOAL · 33</Text></Pressable><View style={s.row}><Pressable onPress={()=>setCount(0)} style={s.secondary}>{ico('refresh-outline',19,C.green)}<Text style={s.secondaryText}>Reset</Text></Pressable><Pressable onPress={()=>setCount(33)} style={s.secondary}>{ico('flag-outline',19,C.green)}<Text style={s.secondaryText}>Complete</Text></Pressable></View></View></Page>}
function DataTool({route,navigation}:any){
 const {location}=useAppLocation(); const title=route.name; const[items,setItems]=useState<any[]>([]); const[error,setError]=useState(''); const[loaded,setLoaded]=useState(false);
 const load=async()=>{setError('');setLoaded(false);try{if(title==='Duas')setItems(await getDuas('morning'));else if(title==='99 Names')setItems(await getNames());else if(title==='Hadith')setItems([await getDailyHadith()]);else if(title==='Mosques'){if(!location){setItems([]);return}setItems(await getNearbyMosques(location.latitude,location.longitude));}}catch(e:any){setError(e.message)}finally{setLoaded(true)}};
 useEffect(()=>{load()},[title,location?.latitude,location?.longitude]);
 return <Page><ToolBar title={title} navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}><LiveBadge source="ISLAMIC.APP"/><Text style={s.dataTitle}>{title==='Duas'?'Morning remembrance':title==='99 Names'?'The Beautiful Names':title==='Hadith'?'Hadith of the day':'Mosques near you'}</Text>{title==='Mosques'&&!location?<LocationPrompt compact/>:error?<ErrorState message={error} retry={load}/>:!loaded?<Spinner/>:!items.length?<View style={s.empty}><View style={s.errorIcon}>{ico('location-outline',24,C.green)}</View><Text style={s.errorTitle}>No live records nearby</Text><Text style={s.errorText}>The islamic.app directory does not currently list a public mosque within 50 km of this location.</Text></View>:items.map((item:any,i)=><View key={item.number||item.slug||i} style={s.dataCard}>{title==='99 Names'?<><Text style={s.dataArabic}>{item.name}</Text><Text style={s.dataName}>{item.transliteration}</Text><Text style={s.dataBody}>{item.meaning}</Text></>:title==='Hadith'?<><Text style={s.dataBody}>{item.text}</Text><Text style={s.dataMeta}>{item.collection?.toUpperCase()} · {item.number}</Text></>:title==='Mosques'?<><Text style={s.dataName}>{item.name}</Text><Text style={s.dataBody}>{item.city}, {item.country}</Text><Text style={s.dataMeta}>{item.distance_km?.toFixed?.(1)} km · {item.source}</Text></>:<><Text style={s.dataArabic}>{item.arabic}</Text><Text style={s.dataBody}>{item.translation}</Text><Text style={s.dataMeta}>{item.category}</Text></>}</View>)}</ScrollView></Page>
}
function HijriCalendarScreen({navigation}:any){const{location}=useAppLocation();const[days,setDays]=useState<CalendarDay[]>([]);const[error,setError]=useState('');const now=new Date();const load=async()=>{if(!location)return;setError('');setDays([]);try{setDays(await getGregorianCalendar(location.latitude,location.longitude,now.getMonth()+1,now.getFullYear()))}catch(e:any){setError(e.message)}};useEffect(()=>{load()},[location?.latitude,location?.longitude]);const first=days[0]?.gregorian.split('-').map(Number);const offset=first?new Date(first[2],first[1]-1,first[0]).getDay():0;return <Page><ToolBar title="Hijri calendar" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}>{!location?<LocationPrompt compact/>:<><View style={s.calendarIntro}><LiveBadge source="ALADHAN"/><Text style={s.calendarMonth}>{now.toLocaleDateString('en',{month:'long',year:'numeric'})}</Text><Text style={s.calendarHijri}>{days.length?`${days[0].hijriMonth} – ${days[days.length-1].hijriMonth} ${days[0].hijriYear} AH`:''}</Text></View>{error?<ErrorState message={error} retry={load}/>:!days.length?<Spinner/>:<><View style={s.weekHead}>{['S','M','T','W','T','F','S'].map((d,i)=><Text key={i} style={s.weekLabel}>{d}</Text>)}</View><View style={s.calendarGrid}>{Array.from({length:offset}).map((_,i)=><View key={`e${i}`} style={s.calendarCell}/>) }{days.map((d,i)=><View key={d.gregorian} style={[s.calendarCell,d.gregorian.startsWith(String(now.getDate()).padStart(2,'0'))&&s.calendarToday]}><Text style={s.gregorianDay}>{i+1}</Text><Text style={s.hijriDay}>{d.hijriDay}</Text></View>)}</View><View style={s.calendarLegend}><View style={s.legendDot}/><Text style={s.sourceBody}>Large number: Gregorian · Small number: Hijri</Text></View></>}</>}</ScrollView></Page>}
function RamadanScreen({navigation}:any){const{location}=useAppLocation();const[days,setDays]=useState<CalendarDay[]>([]);const[year,setYear]=useState<number|null>(null);const[error,setError]=useState('');const load=async()=>{if(!location)return;setError('');setDays([]);try{const snap=await getPrayerSnapshot(location.latitude,location.longitude);const target=snap.hijriMonth>9?snap.hijriYear+1:snap.hijriYear;setYear(target);setDays(await getRamadanCalendar(location.latitude,location.longitude,target));}catch(e:any){setError(e.message)}};useEffect(()=>{load()},[location?.latitude,location?.longitude]);return <Page><ToolBar title="Ramadan" navigation={navigation}/><ScrollView contentContainerStyle={s.dataPage}>{!location?<LocationPrompt compact/>:<><LinearGradient colors={['#2D295E','#6551B5','#A84F73']} style={s.ramadanHero}><LiveBadge source="ALADHAN"/><Text style={s.ramadanArabic}>رَمَضَان</Text><Text style={s.ramadanTitle}>Ramadan {year||''} AH</Text><Text style={s.ramadanSub}>A live 30-day Suhoor and Iftar timetable for {location.label}.</Text></LinearGradient>{error?<ErrorState message={error} retry={load}/>:!days.length?<Spinner/>:<><Section title="Fasting timetable" action={`${days.length} days`}/><View style={s.ramadanList}>{days.map(d=>{const fajr=d.prayers.find(p=>p.name==='Fajr');const maghrib=d.prayers.find(p=>p.name==='Maghrib');return <View key={d.gregorian} style={s.ramadanRow}><View style={s.ramadanDay}><Text style={s.ramadanDayNo}>{d.hijriDay}</Text><Text style={s.ramadanDayLabel}>RAM</Text></View><View style={{flex:1}}><Text style={s.ramadanDate}>{d.weekday} · {d.gregorian}</Text><Text style={s.meta}>{location.label}</Text></View><View style={s.fastTime}><Text style={s.fastLabel}>SUHOOR</Text><Text style={s.fastValue}>{fajr?.time}</Text></View><View style={s.fastTime}><Text style={s.fastLabel}>IFTAR</Text><Text style={s.fastValue}>{maghrib?.time}</Text></View></View>})}</View></>}</>}</ScrollView></Page>}
function ZakatScreen({navigation}:any){const[value,setValue]=useState('');const total=Number(value.replace(/,/g,''))||0;return <Page><ToolBar title="Zakat calculator" navigation={navigation}/><View style={s.dataPage}><Text style={s.dataTitle}>Calculate with clarity</Text><Text style={s.intro}>Enter your eligible wealth after deductible liabilities. Confirm the nisab threshold with a qualified local scholar.</Text><Text style={s.inputLabel}>ZAKATABLE WEALTH</Text><TextInput keyboardType="numeric" value={value} onChangeText={setValue} placeholder="0.00" style={s.moneyInput}/><LinearGradient colors={['#302B68','#735AC4','#C05A78']} style={s.zakatResult}><Text style={s.nextCardLabel}>ESTIMATED ZAKAT · 2.5%</Text><Text style={s.zakatNo}>{(total*.025).toLocaleString(undefined,{maximumFractionDigits:2})}</Text></LinearGradient></View></Page>}
function ExploreStack(){return <Stack.Navigator screenOptions={{headerShown:false}}><Stack.Screen name="ExploreHome" component={ExploreHome}/><Stack.Screen name="Qibla" component={QiblaScreen}/><Stack.Screen name="Tasbih" component={TasbihScreen}/>{['Duas','99 Names','Hadith','Mosques'].map(x=><Stack.Screen key={x} name={x} component={DataTool}/>) }<Stack.Screen name="Zakat" component={ZakatScreen}/></Stack.Navigator>}
function PrayerStack(){return <Stack.Navigator screenOptions={{headerShown:false}}><Stack.Screen name="PrayerHome" component={PrayerScreen}/><Stack.Screen name="Qibla" component={QiblaScreen}/><Stack.Screen name="Hijri Calendar" component={HijriCalendarScreen}/><Stack.Screen name="Ramadan" component={RamadanScreen}/><Stack.Screen name="Mosques" component={DataTool}/></Stack.Navigator>}
function SettingsScreen(){const[reminders,setReminders]=useState(true);const[arabic,setArabic]=useState(false);return <Page><ScrollView contentContainerStyle={s.scroll}><TopBar overline="PRIVATE BY DESIGN" title="Settings" right={<IconButton name="shield-checkmark-outline"/>}/><LinearGradient colors={['#2D295E','#6654B8','#0B7891']} style={s.privacyHero}><MotionGlyph name="shield-checkmark-outline" size={25} inverse/><View style={{flex:1}}><Text style={s.profileName}>No account. No tracking.</Text><Text style={s.profileSub}>Your worship stays private and your preferences remain on this device.</Text></View></LinearGradient><View style={s.privacyPoints}><View style={s.privacyPoint}>{ico('person-remove-outline',19,C.green)}<Text style={s.privacyPointText}>No sign-up</Text></View><View style={s.privacyPoint}>{ico('cloud-offline-outline',19,C.green)}<Text style={s.privacyPointText}>No cloud profile</Text></View><View style={s.privacyPoint}>{ico('analytics-outline',19,C.green)}<Text style={s.privacyPointText}>No ad tracking</Text></View></View><Section title="Preferences"/><View style={s.settings}>{[['notifications-outline','Prayer reminders','Adhan and gentle alerts',<Switch value={reminders} onValueChange={setReminders} trackColor={{true:C.green}}/>],['language-outline','Arabic interface','واجهة عربية',<Switch value={arabic} onValueChange={setArabic} trackColor={{true:C.green}}/>],['calculator-outline','Calculation method','Gulf Region',ico('chevron-forward',18,C.muted)],['text-outline','Quran reading','Uthmani · Sahih International',ico('chevron-forward',18,C.muted)]].map((item:any,index:number)=><View key={item[1]} style={s.setting}><MotionGlyph name={item[0]} size={19} delay={index*45}/><View style={{flex:1}}><Text style={s.settingName}>{item[1]}</Text><Text style={s.meta}>{item[2]}</Text></View>{item[3]}</View>)}</View><View style={s.sourceCard}>{ico('server-outline',21,C.green)}<View><Text style={s.sourceTitle}>Live, keyless data sources</Text><Text style={s.sourceBody}>islamic.app · Al Quran Cloud · AlAdhan</Text></View></View></ScrollView></Page>}
function Tabs(){const{width}=useWindowDimensions();const web=Platform.OS==='web';const barWidth=Math.min(Math.max(width-24,340),640);const responsiveBar=web?{left:'50%' as any,right:undefined,width:barWidth,transform:[{translateX:-barWidth/2}]}:{};return <Tab.Navigator screenOptions={({route})=>({headerShown:false,tabBarHideOnKeyboard:true,tabBarActiveTintColor:C.green,tabBarInactiveTintColor:'#8B909D',tabBarStyle:[s.tabbar,responsiveBar],tabBarLabelStyle:s.tabLabel,tabBarIcon:({color,focused})=>ico(({Today:focused?'home':'home-outline',Prayer:focused?'time':'time-outline',Quran:focused?'book':'book-outline',Library:focused?'grid':'grid-outline',Settings:focused?'settings':'settings-outline'}as any)[route.name],21,color)})}><Tab.Screen name="Today" component={HomeScreen}/><Tab.Screen name="Prayer" component={PrayerStack}/><Tab.Screen name="Quran" component={QuranStack}/><Tab.Screen name="Library" component={ExploreStack}/><Tab.Screen name="Settings" component={SettingsScreen}/></Tab.Navigator>}
export default function App(){const[fontsLoaded]=useFonts({DMSans_400Regular,DMSans_600SemiBold,DMSans_700Bold,Newsreader_600SemiBold,NotoNaskhArabic_400Regular,NotoNaskhArabic_600SemiBold});if(!fontsLoaded)return <SafeAreaView style={s.safe}><Spinner/></SafeAreaView>;return <LocationProvider><NavigationContainer><ExpoStatusBar style="dark"/><Tabs/></NavigationContainer></LocationProvider>}

